package com.cartalaap.marketplace;
import java.time.Instant;import com.cartalaap.user.User;import jakarta.persistence.Column;import jakarta.persistence.EmbeddedId;import jakarta.persistence.Entity;import jakarta.persistence.FetchType;import jakarta.persistence.JoinColumn;import jakarta.persistence.ManyToOne;import jakarta.persistence.MapsId;import jakarta.persistence.PrePersist;import jakarta.persistence.Table;
@Entity @Table(name="marketplace_favorites") public class MarketplaceFavorite{@EmbeddedId private FavoriteId id;@MapsId("userId")@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id")private User user;@MapsId("listingId")@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="listing_id")private MarketplaceListing listing;@Column(name="created_at")private Instant createdAt;protected MarketplaceFavorite(){}public MarketplaceFavorite(User user,MarketplaceListing listing){id=new FavoriteId(user.getId(),listing.getId());this.user=user;this.listing=listing;}@PrePersist void onCreate(){createdAt=Instant.now();}public MarketplaceListing getListing(){return listing;}}
